-- ----------------------------
-- Table structure for accounts
-- ----------------------------
DROP TABLE IF EXISTS `accounts`;
CREATE TABLE `accounts`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `password` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `salt` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `second_password` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `second_salt` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `state` tinyint(1) UNSIGNED NOT NULL,
  `last_login` datetime(0) NULL DEFAULT NULL,
  `created` datetime(0) NOT NULL,
  `birthday` date NULL DEFAULT NULL,
  `banned` tinyint(1) UNSIGNED NOT NULL,
  `ban_reason` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `gm` int(11) NOT NULL,
  `email` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `mac` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `temp_ban` datetime(0) NULL DEFAULT NULL,
  `g_reason` tinyint(4) UNSIGNED NULL DEFAULT NULL,
  `cash` bigint(20) NULL DEFAULT NULL,
  `m_points` bigint(20) NULL DEFAULT NULL,
  `gender` tinyint(1) NOT NULL,
  `session_ip` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `points` bigint(20) NOT NULL,
  `v_points` bigint(20) NOT NULL,
  `last_logon` datetime(0) NULL DEFAULT NULL,
  `expiration` datetime(0) NULL DEFAULT NULL,
  `vip` int(11) NULL DEFAULT NULL,
  `money` bigint(20) NOT NULL,
  `money_b` bigint(20) NOT NULL,
  `last_gain_hm` bigint(20) NOT NULL,
  `paypal_nx` int(11) NULL DEFAULT NULL,
  `modified` datetime(0) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `name`(`name`) USING BTREE,
  INDEX `ranking1`(`id`, `banned`, `gm`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Compact;

