INSERT INTO `wz_itemdata` VALUES (2430242, '摩托车使用券', '', '双击可以从当天起，在10天内使用骑宠技能[摩托车]。', 100, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2430243, '超能套装使用券', '', '双击可以从当天起，在10天内使用骑宠技能[超能套装]。', 100, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
