INSERT INTO `wz_itemdata` VALUES (2430089, '红色幸运饼干 ', '', '升级后获得的红色饼干。双击可以获得礼物。搜集到一定数量后，可以在卡珊德拉那里交换更好的礼物。 ', 1000, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2430151, '升级册(30)', '', '#c使用后直接升1级#的神奇册子，但30级以后无法继续使用。\\n注意事项：升级虽快，但建议玩家不要一次性将册子用尽，按阶段和需求逐步使用。转职、技能、加点等重要事项需玩家自行及时完成，#c如因升级过快造成的损失，需自行承担后果。#', 100, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2430152, '升级册(70)', '', '#c使用后直接升1级#的神奇册子，但70级以后无法继续使用。\\n注意事项：升级虽快，但建议玩家不要一次性将册子用尽，按阶段和需求逐步使用。转职、技能、加点等重要事项需玩家自行及时完成，#c如因升级过快造成的损失，需自行承担后果。#', 100, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2430154, '新手认证书', '', '使用的话可认证为已完成新手任务,并直接可以移动村庄.', 100, '-1.0', -1, 0, 1152, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
