INSERT INTO `wz_itemdata` VALUES (2433715, '七彩伤害皮肤', '', '变更为七彩伤害皮肤。#c使用伤害皮肤后，在变为其他皮肤前将永久应用#。\\r\\n#c该道具使用后也不会被消耗，在有效时间内可以半永久性地使用。#\\n#c使用后仅限1次，可以放入仓库，在账号内其他角色身上应用。#\\r\\n', 1, '1.0', 1, 0, 272, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
