INSERT INTO `wz_itemdata` VALUES (2434031, '品克缤的礼物箱', '', '品克缤回到异界时留下的礼物。#c双击#时，可以获得以下道具。\\r\\n\\r\\n#c我的朋友是品克缤勋章#\\n#c品克缤变身药水（永久）#\\n#c品克缤的经验值秘药#\\n#c品克缤的提升成长秘药#\\n#c角色栏扩展券#\\r\\n\\r\\n从礼物箱中获得的道具全部#c无法交换#，必须由需要道具的角色使用。\\r\\n#c超能力者无法使用#', 1, '1.0', 1, 0, 272, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2434032, '永久品克缤变身药水', '', '#c双击#后， #c10分钟#内可变身成为品克缤。使用后#c不会消失，#想要解除变身时，只要点击右上方的增益图标即可。', 1, '-1.0', -1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
