INSERT INTO `wz_itemdata` VALUES (2433451, '古老帽子箱', '', '箱子中装有蕴含冒险岛悠久历史的道具。#c双击#使用后，可以从下列道具中随机获得一个。\\r\\n\\r\\n#c[可以获得的道具]#\\r\\n#c- 蓝色斗笠#\\r\\n#c- 绿色斗笠#\\r\\n#c- 褐色斗笠#\\r\\n#c- 长老斯坦之帽#\\r\\n#c- 枫叶头盔#', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
