INSERT INTO `wz_itemdata` VALUES (2433479, 'M.I.B文化商品劵礼品劵', '', '只有M.I.B要员才能购买的特殊礼品劵，通过该礼品劵将有机会获得#c文化商品劵#。#c双击#使用后，可以参加该物品的抽奖，并且礼品劵#c可重复使用。# \\r\\n\\r\\n所选的M.I.B要员将在#c2015年1月22日公布。#', 100, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
