INSERT INTO `wz_itemdata` VALUES (2434236, '呆萌鲸鱼骑宠', '', '按攻击键时鲸鱼会喷水。和可爱鲸鱼一起冲浪去吧。#c双击#使用后，可以获得呆萌鲸鱼骑宠技能。', 1, '1.0', 1, 0, 16, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2434125, '闪炫魔方碎片', '', '闪炫魔方的碎片。双击道具进行使用，可以兑换成有用的道具。', 100, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2434039, '战斗机器人（女）交换券', '', '可获得战场上的战斗机器人交换券。点击战斗机器人时，可使用杂货商店，角色死亡时，经验值不会下降，并能让角色在目前的位置上复活。复活时，会恢复所有的HP/MP，并获得战斗机器人特有的Buff及维持死亡前的所有Buff效果。', 1, '1.0', 1, 0, 16, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2434038, '战斗机器人（男）交换券', '', '可获得战场上的战斗机器人交换券。点击战斗机器人时，可使用杂货商店，角色死亡时，经验值不会下降，并能让角色在目前的位置上复活。复活时，会恢复所有的HP/MP，获得战斗机器人特有的Buff，并维持死亡前的所有Buff效果。', 1, '1.0', 1, 0, 16, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2434360, '永久权雪花骑宠', '', '双击之后，可永久使用骑宠技能[权雪花骑宠]。', 1, '1.0', 1, 0, 16, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2434363, '星缘的报答', '', '星缘为了感谢完成冒险岛旗帜图案的玩家而制作的箱子。\\n#c双击鼠标，可以查看里面的东西。但需要注意的是，制作国庆节旗帜活动结束后，里面的东西就会消失。#', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2434364, '国庆节庆祝箱', '', '庆祝国庆节的礼物箱。\\n#c双击鼠标，可以查看里面的东西。但活动时间结束后，里面的东西就会消失。#', 100, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2434375, '篝火伤害皮肤', '', '应用篝火伤害皮肤。\\r\\n#c一旦使用，永久有效，直到更换其他皮肤。\\r\\n\\r\\n\\r\\n', 1, '-1.0', -1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2434376, '篝火随机箱', '', '冒险岛森林乌萨掉落的箱子。#c双击#可获得随机礼品。', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2434373, '高级月饼', '', '兔儿奶奶获得月之气息后制成的特制月饼。双击吃下美味月饼后，#c还可以提升经验值。', 100, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2434374, '满月清辉伤害皮肤', '', '变更为满月清辉伤害皮肤。\\n暴击时，将会激发出满月效果。\\n#换成其他伤害皮肤之前，该皮肤永久有效。', 1, '1.0', 1, 0, 16, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (2434469, '黄金月饼', '', '好吃又实用的完美黄金月饼。\\n#c持续时间30分钟\\n物理攻击力+20#\\n#魔法攻击力+20#\\n#经验值获得量1.5倍#\\r\\n和好友一起分享，持续时间变成2倍！将鼠标放在需要分享黄金月饼的好友角色身上，点击右键，选择‘赠送黄金月饼’，便可作为礼物赠送。', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
