INSERT INTO `wz_itemdata` VALUES (4031217, '黄金钥匙', '', '黄金所打造的钥匙，会发出白色的光辉。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4031218, '黑暗契约书', '', '可以让踏上死亡之路的生命重新复活的力量根源。在陈旧的纸上写着和恶魔签订的灵魂契约以及恶魔的印记。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4031219, '斯卡德的弓', '', '斯卡德为了他亲爱的弟弟伊卡图所制作的弓。轻巧、坚固并且具有威猛的攻击力。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4031220, '神秘的面粉', '', '糕点师傅库可斯制作巧克力棒所使用的神秘面粉。', 1, '500.0', 500, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4031221, '地球防卫总部特殊移动胶囊', '', '只有隶属于地球本部的成员才能使用的移动胶囊。与一般移动胶囊不同，就算是在不同的大陆仍可瞬间移动到地球防卫总部。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4031222, '钢铁锄', '', '耕田时所使用的器具，因用钢铁所制程，所以不易折断', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4031223, '金银宝物', '', '里面装有许多从兴夫的瓜中所获得的宝物。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4031224, '财产扣押通知书', '', '从乐夫的瓜中所出现的财产扣押通知书。\\n上面写有○○年 ○○月 ○○日将财产进行扣押的内容。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4031225, '瓜子', '', '飞往南部的燕子所提供的小而色白的瓜子，在适当的地方播种后就会发芽结果', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4031226, '葛温的书包', '', '虽不晓得里面装有什么，但这个背包相当沉重，背包背面一角写着小小的葛温。', 1, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
