INSERT INTO `wz_itemdata` VALUES (4032479, '培训导师徽章', '', '勇士部落培训导师的身份徽章', 100, '-1.0', -1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4032480, '斯坦海伦吉他', '', '音乐可以看到内心深处的痛苦根源，而它总可以揭示事情真相。 - 长老斯坦', 100, '-1.0', -1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4032481, '不合适的奥卡利那笛', '', '缺了一些孔，似乎做工非常粗糙。但音色不错。', 100, '-1.0', -1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4032482, '达克韦恩的怪兽鼓', '', '你必须要有生活的激情，这样其他人也知道该如何去享受生活。 - 达克鲁的分身 -', 100, '-1.0', -1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
