INSERT INTO `wz_itemdata` VALUES (4032484, '凯琳亨德里克斯吉他', '', '演奏这首音乐，直到你血脉喷张，乐曲在你的骨骼中跳动…-凯琳', 100, '-1.0', -1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
