INSERT INTO `wz_itemdata` VALUES (4032487, '改善的燧石', '', '热度很高，能够从远处蒸发水份。用在经过简单清理的藏宝图上。', 100, '-1.0', -1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4032488, '阿言蒙塔娜的麦克风', '', '我热爱生活，如同热爱这首悦耳的歌曲…- 阿言 - （用在肮脏的藏宝图上）', 100, '-1.0', -1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
