INSERT INTO `wz_itemdata` VALUES (4032579, '粉嫩饺子面粉', '', '粉扑扑的奇妙饺子面粉，可揉捏出令人开心的饺子皮。是制作节日饺子的上品。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4032580, '活力鲜肉', '', '时刻透出无限活力的鲜肉，据说吃了会让人精力充沛。是制作节日饺子的上品。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4032581, '恬静白菜', '', '沉浸于安详恬静中的白菜，据说吃了能让人保持冷静。是制作节日饺子的上品。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4032582, '益寿春卷皮', '', '添药草精华的春卷皮，据说可以给人带来更多健康。是制作节日春卷的上品。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4032583, '福气肉馅', '', '向流星许愿过的肉馅，据说可以给人带来更多福气。是制作节日春卷的上品。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4032584, '财运豆油', '', '用金豆子制作的豆油，据说可以给人带来更多财运。是制作节日春卷的上品。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4032585, '缠绵糯米', '', '天天黏黏的特级糯米，据说可以把人们的心联系在一起。今年做节日年糕的上品。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
