INSERT INTO `wz_itemdata` VALUES (4032592, '黄金饺子王', '', '喜气饺子抱团祝贺，只有汇聚更多佳品才进化成的黄金饺子王！给各位送上更多祝福了，节日快乐！', 100, '1.0', 1, 0, 128, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
