INSERT INTO `wz_itemdata` VALUES (4220067, '月亮照片信封', '', '装着月亮照片的信封。为了不被跳跃的冲击损坏，特地用结实的纸制作而成。获得月亮照片碎片后，可以双击打开信封，然后把照片碎片拖放进去。', 1, '100.0', 100, 0, 656, 0, 0, 0, 0, 10041, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4220137, '提提阿纳的蛋', '', '骑士团专用骑宠——提提阿纳的蛋。可以通过共享经验值培养。孵化之后交给骑宠教官奇里杜。', 1, '100.0', 100, 0, 656, 0, 0, 0, 0, 20514, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4220138, '玻璃温室', '', '装有提提阿纳的玻璃温室。可以通过喂食培养。养成后带着去见骑宠教官奇里杜。', 1, '100.0', 100, 0, 656, 0, 0, 0, 0, 20516, '', '', 0, '', 0, '', 0, '');
