INSERT INTO `wz_itemdata` VALUES (4220148, '花蘑菇的画像', '', '可以画花蘑菇画像的图纸。使用神奇的颜料,神秘的颜料，魔法颜料即可完成花蘑菇图像。 r\\n#c鼠标双击可以打开。#', 1, '1.0', 1, 0, 640, 0, 0, 0, 0, 10288, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (4220149, '三眼章鱼的画像', '', '可以画三眼章鱼画像的图纸。使用神奇的颜料,神秘的颜料，魔法颜料即可完成三眼章鱼图像。r\\n#c鼠标双击可以打开。#', 1, '1.0', 1, 0, 640, 0, 0, 0, 0, 10289, '', '', 0, '', 0, '', 0, '');
