INSERT INTO `wz_itemdata` VALUES (3010631, '金龙鱼椅子', '', ' 金光闪闪的巨型金龙鱼。坐在上面时，每10秒HP恢复200点，MP恢复200点。', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3010632, '印第安小孩的朋友', '', '和印第安村庄中生长出来的新芽一起，沉醉在丛林的寂静中吧。每10秒HP恢复50点，MP恢复50点。', 1, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3010633, '印第安元老的兄弟', '', '真诚的印第安元老们，坐下来感觉很有负担。坐在上面时，每10秒HP恢复50点，MP恢复50点。', 1, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3010636, '蝙蝠怪椅子', '', '来吧！能坐在蝙蝠魔腿上的胆大之人会是谁呢？\\n每10秒HP恢复50。', 1, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
