INSERT INTO `wz_itemdata` VALUES (3010715, '幸福9周年蛋糕气球椅', '', '让我们乘着幸福与喜悦的气球向梦想起飞。9周年玩家设计大赛纪念作品，由中国玩家“小术”设计。坐在上面，每10秒恢复HP、MP各200。', 1, '1.0', 1, 0, 16, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
