INSERT INTO `wz_itemdata` VALUES (3010823, '蘑菇智能手表椅子', '', '蘑菇智能手表，身份的象征！坐下后，每10秒HP、MP各恢复70。由东南亚服玩家“MADhybridz”设计的蘑菇智能手表椅子。', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3010824, '水星椅子', '', '又小又很热！但可以缓解肌肉酸痛。每10秒钟恢复HP,MP各60。', 1, '1.0', 1, 0, 256, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3010825, '金星椅子', '', '很厚又冒烟并且非常非常热！如果你可以忍受，它就像毛毯一样为你保暖。\\n每10秒钟恢复HP,MP各60。', 1, '1.0', 1, 0, 256, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3010826, '地球椅子', '', '这蓝色星球是充满生气的，非常熟悉的地方。\\n每10秒钟恢复HP,MP各60。', 1, '1.0', 1, 0, 256, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3010827, '火星椅子', '', '这里有水吗？这里有外星人吗？请坐在这椅子上找出他们！\\n每10秒钟恢复HP,MP各60。', 1, '1.0', 1, 0, 256, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3010828, '木星椅子', '', '这是为宇宙掌控者的又大、又猛烈的椅子。\\n每10秒钟恢复HP,MP各60。', 1, '1.0', 1, 0, 256, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
