INSERT INTO `wz_itemdata` VALUES (3010921, '彩蛋篮子', '', '篮子中塞满五彩缤纷的彩蛋!\\n每10秒钟恢复HP40,MP40.', 1, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
