INSERT INTO `wz_itemdata` VALUES (3010935, '狗狗酣睡椅子', '', '和可爱的狗狗们一起呼呼大睡，进入梦乡吧。坐下后，每10秒HP、MP各恢复100。', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
