INSERT INTO `wz_itemdata` VALUES (3020020, '礼物箱子', '', '可储存打猎经验值10%的礼物箱子(不包含组队额外经验值，任务补偿经验值)。没有MP、HP恢复功能。坐在椅子上，便可获得椅子上所累积的经验值。将鼠标移过去，便可确认已获得的经验值%。玩家使用鼠标右键来指定所要累积经验值的椅子，而选定的椅子周围，会出现红色框框以作区分。椅子内所累积的经验值，会在玩家注销后48小时后自动消失。', 1, '5000.0', 5000, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
