INSERT INTO `wz_itemdata` VALUES (3994085, '运营员的蜡烛', '', '运营员交给玩家的小蜡烛。游戏结束时，蜡烛熄灭并消失。', 1, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
