INSERT INTO `wz_itemdata` VALUES (3994095, '测试先锋的信物', '', '拥有此信物可获取冒险岛测试区账号一个，请联系官方客服，留下你的获奖账号和安全的联系方式，核实信息后将给予发奖。本信物仅作为荣誉证明和领奖提示，不作为获奖凭证。', 1, '1.0', 1, 0, 1168, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
