INSERT INTO `wz_itemdata` VALUES (3994434, '冰凉运动饮料', '', '比水吸收更快的运动饮料冻成了冰块。哎呀，好冷～', 1, '1.0', 1, 0, 1072, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
