INSERT INTO `wz_itemdata` VALUES (3994436, '忍耐艾草幼苗', '', '拥有神秘力量的艾草幼苗。以忍耐之心持有1小时，就会变成长大的艾草。', 1, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994437, '长大的忍耐艾草', '', '经过耐心等待后，叶子长得非常茂盛的忍耐艾草。', 100, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994438, '伤感星星', '', '夹在书页中的长得像星星的枫叶。看着让人感觉有点伤感。每天夹在中间3～4小时，就会慢慢变干。\\n#c退出游戏时消失。#', 1, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
