INSERT INTO `wz_itemdata` VALUES (3994443, '助威花球', '', '用作助威道具的花球。带在身上，每30分钟可以获得增益。\\n#c退出游戏时消失。#', 100, '0.0', 0, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994444, '时间机器', '', '可以进行时间旅行的装置。有将时间干涉现象最小化的功能。', 1, '0.0', 0, 0, 1168, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994445, '回归者怀表', '', '送给很久没有回到冒险岛世界来的玩家的小怀表。和其他怀表相比好像走得比较快。\\n#c带在身上时，可以额外获得10%的经验值。#', 1, '0.0', 0, 0, 400, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
