INSERT INTO `wz_itemdata` VALUES (3994501, '情人节巧克力', '', '用于记录爱情的情人节巧克力，在背包栏中保存30分钟，也许就能把自己的心意转达给某人…？', 1, '1.0', 1, 0, 1072, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994502, '充满爱意的情人节巧克力', '', '写着爱情信息的情人节巧克力，交给爱情信使卡珊德拉就一定能转达爱意！', 1, '1.0', 1, 0, 1072, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994506, '秋之风车', '', '像秋实那样丰盛的风车，用这个风车和秋风游玩30分钟，卡珊德拉就会印上星星图章。', 1, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
