INSERT INTO `wz_itemdata` VALUES (3994509, '恋爱占卜水晶球', '', '卡珊德拉托付的水晶球，带在身上满30分钟就能知道今年的爱情运势了。', 1, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994510, '闪亮的恋爱占卜水晶球', '', '闪烁着神秘之光的恋爱占卜水晶球。去找卡珊德拉给我占卜爱情运吧。', 100, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994665, '诺巴的空玻璃瓶', '', '卡珊德拉给你的玻璃瓶。等待30分钟后，会充满神圣的灵魂。', 1, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994666, '诺巴的满当当玻璃瓶', '', '已持有诺巴的空玻璃瓶30分钟，充满了灵魂。再次交给卡珊德拉吧。', 100, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994514, '神圣拯救者之石', '', '蕴含着神圣拯救者的力量的石头。带在身上消灭怪物时，可以积累技能值，填满之后就可以用普通攻击键施展神圣拯救者的祝福，该技能可以与其他增益叠加使用，持续1小时。\\r\\n#c正在使用神圣拯救者的祝福效果时，不再积累技能值，达到31级、71级就可以获得更加强大的祝福力量。#', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994518, '充满回忆的照相机 ', '', '曾经记录过与扎昆的片段，现在用于保存遗物现场的相机。', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994519, '休彼德蔓的热气球发动机', '', '启动热气球，给遗物发掘现场提供全景照明时使用。', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994520, '100%发现探针', '', '感觉只要刺进去就能100%找到东西的探针。刺得太用力可能会损坏遗物。', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994521, '奇怪画廊的遗物地图', '', '好像在奇怪画廊里的画中出现过的遗物地图。', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994522, '遗物现场所必需的罗盘', '', '为找到遗物的精确位置所必需的罗盘。', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994523, '驱赶霉运的胡须梳', '', '认为只有把胡须梳整齐了才能提高发现遗物概率的休彼德蔓的胡须梳。', 1, '1.0', 1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
