INSERT INTO `wz_itemdata` VALUES (3994651, '万圣节推荐券', '', '可以在万圣节活动期间每天#c下午8点#举行的化妆舞会的星星时刻中获得特殊礼物的推荐券。把推荐券弄丢了的话，就无法参加化妆舞会的星星时刻。', 1, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994652, '', '', '', 100, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
