INSERT INTO `wz_itemdata` VALUES (3994655, '枫叶城堡邀请信', '', '邀请到枫叶城堡去的邀请信。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994656, '0分考卷', '', '写着<魔法学0分，请继续努力。>的考卷。看上去非常陈旧。', 100, '-1.0', -1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994657, '陈旧的日记本', '', '用心怀恐惧的小学生的字体写成的陈旧的日记本。', 100, '-1.0', -1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994658, '签名板', '', '同意关闭学校的有所有学生签名的石板。', 100, '-1.0', -1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994659, '封印纹章', '', '雕刻着<亲爱的人们，别忘记满月会在10月归来>字样的意味深长的封印纹章。', 100, '-1.0', -1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994660, '舞会服装箱', '', '装着华丽的舞会服装的箱子。遗憾的是箱子被锁了起来，无法打开。', 100, '-1.0', -1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994661, '希纳斯的情书', '', '充满了希纳斯的爱的情书，真想打开看看。', 100, '-1.0', -1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994662, '第一季酱鸡', '', '适合在观看冒险岛第一季时吃的酱鸡。', 100, '0.0', 0, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994663, '奇怪的紫色书信', '', '枫叶城堡的幽灵们掉落的奇怪的紫色书信。', 100, '-1.0', -1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994664, '舞会服装箱', '', '装着华丽的舞会服装的箱子。遗憾的是箱子被锁了起来，无法打开。', 100, '-1.0', -1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994667, '火花碎片', '', '在自由市场的#c糖果女孩#NPC处可以制作成一个完整的神奇火花。', 100, '-1.0', -1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994668, '四叶草叶子', '', '象征幸运的四叶草的叶子。在30分钟内带在身上，可以获得四叶草的幸运。', 1, '1.0', 1, 0, 1072, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994669, '幸运四叶草', '', '保管得非常小心，充满了幸运的四叶草', 1, '1.0', 1, 0, 1712, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994670, '粉色珠子', '', '卡珊德拉给的粉色珠子。据说把它带在身上，在1小时内保持在线，就会变成跳动的心珠……要试试看吗？但中途退出时，珠子就会消失，一定要注意！', 1, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994671, '跳动的心珠', '', '卡珊德拉给的粉色珠子变成了跳动的心珠。这个珠子里到底装着谁的心呢？', 100, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994673, '黄枫叶', '', '卡珊德拉给的黄枫叶。据说把它带在身上，在30分钟内保持在线，就会变成秋日红枫叶……但中途退出时，枫叶就会消失，一定要注意！', 1, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994674, '秋日红枫叶', '', '被秋天染成红色的枫叶。冒险岛世界的村庄真是美丽得让人窒息！', 100, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994675, '雪铲', '', '铲雪时使用的雪铲。可以在有雪堆的地方使用。但中途退出游戏时会消失。一定要注意！', 100, '-1.0', -1, 0, 544, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994676, '手炉', '', '可以暖手的便携式手炉。但中途退出游戏时会消失。一定要注意！', 100, '-1.0', -1, 0, 544, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994677, '杯面', '', '只要有热水，可以在任何地方泡着吃的辣味杯面。但中途退出游戏时会消失。一定要注意！', 100, '-1.0', -1, 0, 544, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994685, '融化的雪屋', '', '放置太久全部融化以至于面目全非的雪屋，听说在线30分钟之后，就会重新变回原来的雪屋…', 1, '1.0', 1, 0, 1072, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994686, '坚硬的雪屋', '', '被寒风冻得坚硬的雪屋，充满这冬季的冰寒。', 1, '1.0', 1, 0, 1072, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
