INSERT INTO `wz_itemdata` VALUES (3994717, '特殊花蘑菇藏品石像', '', '可以放在卡珊德拉的藏品箱任何一个地方的特殊花蘑菇金色藏品石像。不管种类是什么，可以放在任何一个地方，完成卡珊德拉的收藏。', 300, '0.0', 0, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
