INSERT INTO `wz_itemdata` VALUES (3994720, '克拉拉的情人节金币', '', '为了纪念情人节而发行的金币。虽然没有实际价值，但是好像在钱币收藏家中间很受欢迎。', 100, '0.0', 0, 0, 1552, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994721, '巧克力块', '', '情人节的时候用剩的巧克力块。不仅量非常大，而且散落在各个地方，在情人节之后变成了让人头疼的垃圾。', 100, '-1.0', -1, 0, 1552, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
