INSERT INTO `wz_itemdata` VALUES (3994735, '风车', '', '快乐地迎接春风的风车。把它交给卡珊德拉吧。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994736, '世界徽章<米乐>', '', '米乐世界的徽章。被合并到伊西诺斯世界中之后，现在已经不再使用了。但是作为记忆，将永远留在所有米乐世界人的心中。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994737, '世界徽章<诺巴>', '', '诺巴世界的徽章。被合并到伊西诺斯世界中之后，现在已经不再使用了。但是作为记忆，将永远留在所有诺巴世界人的心中。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994738, '世界徽章<科司摩>', '', '科司摩世界的徽章。被合并到伊西诺斯世界中之后，现在已经不再使用了。但是作为记忆，将永远留在所有科司摩世界人的心中。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994722, '卡珊德拉的鞋', '', '被夜光鬼偷走的卡珊德拉的花鞋。外表很闪亮，看上去好像买了还没多久。卡珊德拉的脚好像比想象的要小。', 100, '-1.0', -1, 0, 1552, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994723, '细筛子', '', '洞眼非常小的细筛子。是过滤面粉时很好用的一种工具。不过，听说用来驱赶夜光鬼，倒是有很好的效果。喜欢数数的夜光鬼本想来偷鞋子，可数着数着筛子的洞眼时，天就亮了，于是它就回去了。', 100, '-1.0', -1, 0, 1552, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994724, '卡珊德拉的新鞋', '', '买了还不到一天的新花鞋。外表很闪亮，一看就知道买了还没多久。#c退出游戏时，鞋子可能会被夜光鬼偷走。#', 1, '1.0', 1, 0, 1072, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994725, '旧鞋', '', '新鞋被拿在手上到处走，好像沾了不少灰。表面的光消失了。看上去不再是新鞋了。#c退出游戏时，可能会把鞋子弄丢。#', 1, '1.0', 1, 0, 1072, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994726, '坚硬的树枝', '', '看上去适合用来制作风筝的结实的树枝。', 100, '-1.0', -1, 0, 1040, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994825, '闪耀的星星', '', '星星女神掉下的闪闪发光的星星。把它交给卡珊德拉，也许可以获得用星星装饰的帅气的称号……？', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994741, '海马', '', '[博物专用]小巧可爱的海马。长得和真的马一样，但实际的身材要比马小得多。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994742, '彩虹鱼', '', '[博物专用]美丽的彩虹色的鱼。虽然没有蓝色和紫色，但还是被称为彩虹鱼。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994743, '河豚', '', '[博物专用]肚子圆圆的河豚。河豚有毒，吃的时候必须小心。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994744, '小丑鱼', '', '[博物专用]有着漂亮的花纹的鱼。因为长得很滑稽，被称为小丑鱼。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994745, '黄金鱼', '', '黄金鱼身体里到底有没有黄金呢，带着我去#c转蛋屋#使用可以得到意想不到的惊喜。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994746, '金枪鱼（罐头）', '', '[博物专用]金枪鱼在罐头里。当然是加工过的金枪鱼。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994747, '舞痴', '', '[博物专用]看上去不怎么会跳舞的鱼。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994748, '音痴', '', '[博物专用]看上去不怎么会唱歌的鱼。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994749, '节拍痴', '', '[博物专用]看上去不怎么会唱歌，也不怎么会跳舞的鱼。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994750, '竹枪', '', '[博物专用]用竹子做成的枪。用很好的竹子制作而成，看上去很值钱。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994751, '冷冻金枪鱼', '', '[博物专用]冷冻的金枪鱼可以当作强力武器使用。等融化了之后，吃起来也许味道还不错？', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994752, '帅气双枪', '', '[博物专用]只要带在身上就感觉很帅的双枪。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994753, '可爱短刀', '', '[博物专用]漂亮的粉红色可爱短刀。但是实际上非常锋利。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994754, '不错的剑', '', '[博物专用]一看就知道是很不错的剑。传说是有名的剑客使用过的剑。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994755, '亮银锅盖', '', '[博物专用]煮拉面的锅的锅盖，但有时候可以成为不错的战斗装备。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994756, '无敌连身衣', '', '[博物专用]衣服也能成为武器吗？是的。时尚也是武器。感觉穿在身上就能无敌。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
