INSERT INTO `wz_itemdata` VALUES (3994762, '巧克力蛋糕', '', '[博物专用]卡珊德拉最喜欢的巧克力蛋糕。据说为了获得这种巧克力蛋糕，她还特地举行过活动。', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
