INSERT INTO `wz_itemdata` VALUES (3994852, '紧闭的积分礼包', '', '关得紧紧的积分礼包，怀着爱和真诚带着身上1小时的话，说不定能够打开心灵。', 1, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994853, '敞开的积分包', '', '感到了精心和爱心的敞开心扉的积分包裹，快去把那闪光的积分拿过来。', 100, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994854, '热乎乎的杯面', '', '寒冷的冬天，热乎乎的泡面，用这个东西真的能驱散寒意吗…？', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
