INSERT INTO `wz_itemdata` VALUES (3994869, '结实的雪铲', '', '瞬间铲除寒冰的冬日积雪。把严寒赶到九霄云外去吧！', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994870, '炽热的太阳', '', '夏天酷热的元凶--炽热的太阳。', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994871, '被盗的鹅蛋', '', '农场主人所说的被偷的鹅蛋。从外表看，不知道是不是鹅蛋。为何如此执着于普普通通的鹅蛋呢？', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994872, '蓝天扇', '', '可以带来凉风的蓝天扇。据说把这个扇子带在身上并保持15分钟在线的话，可以在卡珊德拉那里获得星星图章。', 1, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994873, '爱的温度', '', '通过捕猎而得到锻炼的蕴含母鸡温暖爱意的温度。说不定可以唤醒瞌睡虫蛋蛋。', 100, '-1.0', -1, 0, 1552, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994893, '甜蜜的蜂蜜', '', '装满了甜蜜的纯天然蜂蜜的蜜罐。做成糖水喝下去, 一定很棒。', 100, '0.0', 0, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994907, '你我约定之证物', '', '为了表示会记住你和我的约定而发放的证物。据说带着它保持在线15分钟的话，可以从卡珊德拉那里获得星星图章。', 1, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
INSERT INTO `wz_itemdata` VALUES (3994909, '关闭的魔法袋', '', '紧闭的魔法口袋，和玉佩在一起的时间超过30分钟后，口袋就会打开。', 1, '1.0', 1, 0, 1200, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
