INSERT INTO `wz_itemdata` VALUES (3994978, '进击的巨人时装回收图章', '', '回收从进击随机箱获得的时装道具，就可以获得奖励图章。收集11个图章，就可以交换到特殊的随机时装！ ', 100, '1.0', 1, 0, 1552, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, '');
