INSERT INTO `wz_oxdata` VALUES (1, 1, '生活在丛林深处的怪猫是可以进行远距离攻击和近身攻击的强力的怪物。', '怪猫只会进行近身攻击。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 2, '火独眼兽、风独眼兽、冰独眼兽是长得差不多的怪物，其中只有火独眼兽有2只眼睛。', '所有的都是1只眼睛。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 3, '骑着扫帚飞来飞去的巫婆用强力的魔法光线攻击远距离的玩家。', '巫婆是近距离攻击的怪物。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 4, '骑着扫帚飞来飞去的巫婆惧怕圣属性魔法。', '巫婆惧怕圣属性魔法。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 5, '矿山僵尸和僵尸之中，僵尸的等级更高。', '两者的等级都是57级。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 6, '会飞的怪物蝙蝠每飞一段时间，就会吊在天花板上休息。', '不休息一直飞行。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 7, '黄金海岸可以看到的长得像梭子蟹的怪物红螃蟹偶尔会跳跃攻击。', '虽然长得像梭子蟹，但是也会跳跃攻击。', 'o');
INSERT INTO `wz_oxdata` VALUES (1, 8, '蓝独角狮是会进行冰冻攻击的怪物。', '是进行冰属性攻击，而且弱点是火属性的怪物。', 'o');
INSERT INTO `wz_oxdata` VALUES (1, 9, '长得像可爱的海龟一样的怪物乌龟会进行强力的远距离攻击。', '乌龟是会远距离攻击的怪物。', 'o');
INSERT INTO `wz_oxdata` VALUES (1, 100, '赤龙是龙系怪物中唯一能进行远距离攻击的怪物。', '赤龙和冰龙都会进行远距离攻击。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 101, '主要生活在沼泽地带的黑鳄鱼是比土龙等级更高的怪物。', '黑鳄鱼是(52级)，土龙是(45级)。', 'o');
INSERT INTO `wz_oxdata` VALUES (1, 102, '在勇士部落的周边可以见到土龙，他是青龙的进化种，远距离攻击是其特征。', '只会近距离攻击，不会远距离攻击。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 103, '冰峰雪域登场的所有怪物，都有惧怕火属性魔法的特点。', '黑雪人、黑企鹅王惧怕圣属性魔法。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 104, '小海狮在受到攻击时，会和头顶上的小海豹分离，一起进行攻击。', '小海狮无法分离。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 105, '等级为100的蝠魔不会因毒魔法而中毒。', '具有使毒魔法无效，惧怕圣魔法的特点。', 'o');
INSERT INTO `wz_oxdata` VALUES (1, 106, '坐着扫帚飞来飞去的巫婆是不死系怪物。', '巫婆虽然惧怕圣属性魔法，但并不是不死系怪物。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 107, '龙虾怪物大龙虾在吃了黄金炸虾之后会更容易捕捉。', '和黄金炸虾没有关系。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 108, '斧木妖是由于伐木工没有拔出斧子，因为怨恨而诞生的怪物。', '传说是由于伐木工没有拔掉斧子而发出怨恨，因此而重生。', 'o');
INSERT INTO `wz_oxdata` VALUES (1, 109, '北半球的水流漩涡是逆时针旋转的.', '水流旋转与地球自转有关，观察一下就知道，我们身处的北半球漩涡是逆时针的！', 'o');
INSERT INTO `wz_oxdata` VALUES (1, 110, '狼人在受到攻击时，会召唤分身进行攻击。', '狼人没有分身。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 111, '童话村里登场的鬼怪中，绿色鬼怪可以用荞麦蒟蒻召唤。', '绿色鬼怪-荞麦蒟蒻', 'o');
INSERT INTO `wz_oxdata` VALUES (1, 112, '童话村里登场的鬼怪中，蓝色鬼怪可以用猪肉串召唤。', '蓝色鬼怪-谷茶', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 113, '童话村里登场的鬼怪中，黄色鬼怪可以用谷茶召唤。', '黄色鬼怪-猪肉串', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 114, '冒险岛中最弱的怪物是“蘑菇仔”。', '不是蘑菇仔，蜗牛才是最弱的怪物。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 115, '动物森林中的狐狸和狸猫的额头上都贴着树叶。', '两种怪物的额头上都贴着树叶。', 'o');
INSERT INTO `wz_oxdata` VALUES (1, 116, '捕捉中国上海郊外的大头鸭可以获得鸭脚。', '可以获得鸭蛋，而不是鸭脚。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 117, '捕捉中国上海郊外的绵羊可以获得羊毛。', '捕捉绵羊可以获得羊毛。', 'o');
INSERT INTO `wz_oxdata` VALUES (1, 118, '中国上海郊外的斗鸡全都是公鸡。', '全都是有大红冠子的公鸡。', 'o');
INSERT INTO `wz_oxdata` VALUES (1, 119, '捕捉中国徐州岔道的山羊，可以获得山羊胡子。', '捕捉山羊，可以获得白色的角。', 'x');
INSERT INTO `wz_oxdata` VALUES (1, 120, '冒险岛的诞生日是7月23日', '对于冒险岛的重要庆典日我们又怎么能记错呢？7月23日是我们共同的节日！', 'o');
INSERT INTO `wz_oxdata` VALUES (2, 1, '勾心斗角原本是指中国古代建筑呈现出的艺术形态', '最初的勾心斗角是艺术的美，现在有点不和谐啊，让我们为了追求美好而努力吧！', 'o');
INSERT INTO `wz_oxdata` VALUES (2, 2, '从商店购买100%卷轴的时候，双手武器卷轴要比单手武器卷轴贵。', '双手武器卷轴和单手武器的价格都一样。', 'x');
INSERT INTO `wz_oxdata` VALUES (2, 3, '魔法密林武器商店出售长杖卷轴和短杖卷轴。', '目前的武器商店并没有直接出售卷轴。', 'x');
INSERT INTO `wz_oxdata` VALUES (2, 100, '要制作弓箭手的手套“绿狩猎手套”，红狩猎手套必须要有的材料。', '必须要有的材料是蓝狩猎手套。', 'x');
INSERT INTO `wz_oxdata` VALUES (2, 101, '五花八门的由来是中国古代有名的花鸟集市闻名遐迩开有八个门的大排场', '其实这完全是胡说的，五花和八门原来是中国古代用兵的2种阵法。', 'x');
INSERT INTO `wz_oxdata` VALUES (2, 102, '道具黄金炸虾可以在水下世界的杂货商人安纳斯那里买到。', '在其他地方没有销售。', 'o');
INSERT INTO `wz_oxdata` VALUES (2, 103, '制作魔法师手套红守护手套时，需要用到动物的皮革共60张。', '需要动物皮革60张，由魔法密林的易德制造。', 'o');
INSERT INTO `wz_oxdata` VALUES (2, 104, '青铜弓矢和钢铁弓矢可以通过弓箭手的村庄(射手村)的比休斯制作。', '比休斯只能制作青铜弓矢。', 'x');
INSERT INTO `wz_oxdata` VALUES (2, 105, '制作提炼石的时候，价钱最贵的提炼石是星石。', '黑暗水晶的价格是50000金币，是最贵宝石。', 'x');
INSERT INTO `wz_oxdata` VALUES (2, 106, '要在未装备的道具上使用卷轴，必须学会“匠人之魂”技能。', '必须学习匠人之魂技能，才能在未装备的道具上使用卷轴。', 'o');
INSERT INTO `wz_oxdata` VALUES (2, 107, '装备窗口的每个空格可以叠放100张怪物卡片。', '可以叠放1,000张怪物卡片。', 'x');
INSERT INTO `wz_oxdata` VALUES (2, 108, '攻击速度为快速的木精灵枪可以在武器销售员百鸟警官那里买到。', '武器销售员百鸟警官那里可以买到木精灵枪。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 1, '暖炉可以在寒冷的天气里使用，使房间变得温暖。', '暖炉也可以用来烤红薯或者加热其他食物。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 2, '植物的茎是输送根部吸收的水的通道。', '植物根部吸收的水分会沿着植物的茎移动。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 3, '放出光线的物体称为“光源”。', '火、阳光、日光灯等都是光源。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 4, '数学中的三角函数，余弦的表示是SIN', '欧欧欧，NO，NO，NO。余弦其实是COS啊！不过并不是动漫里的COSPLAY哦~', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 5, '物体受到光线照射产生的明亮和黑暗成为“明暗”。', '物体的明暗可以让人感受到立体感和量感。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 6, '发现了X射线的科学家名叫伦琴', '是的，X射线也叫伦琴射线，也是伦琴偶然发现的，但绝不是X-MAN发现的哦！', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 7, '绿水灵的珠子要比蓝水灵的大', '这个用你自己的眼睛确认一下印象就深刻了，蓝水灵的珠子比绿水灵的珠子大不少哦', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 8, '夏季由于空调而引起的疾病称为空调病。', '室内外的温度差最好能在5°C左右。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 9, '有一个叫做[什么飞蛋打]的俗语。这里的“什么”是鸡。', '用来描述不相关的两件事同时发生的情况。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 10, '梅雨季节里水果的口味会变差。', '梅雨季节里经常下雨，水果吸收了大量水分之后糖度会下降。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 11, '汗的作用是把体内的废弃物排出体外，以及调节体温和保护皮肤。', '最好能让身体自然地流汗。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 12, '夏季屋内屋外的温差最好能在5°C左右。', '温差大于5°C时，容易得空调病。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 13, '夏季吃太多凉的东西可以导致消化能力下降。', '吃凉的食物容易使人体内部热量不足。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 14, '紧张的时候手心会出汗的原因是血压上升导致体温升高。', '身体在热的时候会试图通过出汗来降低体温。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 15, '电车票和电话卡用磁铁摩擦的话，上面记录的信息就会被清除。', '利用磁铁的性质制作而成的物品靠近磁铁的话，上面的信息可以被清除。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 16, '西瓜是水分很多的水果。', '西瓜中含有的水分占90%以上。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 17, '夏天的夜晚要比冬天长。', '夏天的夜晚要比冬天短。', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 18, '绿水灵的珠子要比蓝水灵的珍稀', '绿水灵的珠子比蓝水灵珠子珍稀许多，不少玩家都在为了绿水灵珠子四处奔波哦', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 19, '要获得休彼德曼的项链必须参加怪物嘉年华赢取一定数量印有休彼德曼头像的纪念币', '特别形状的纪念币上印刻的是枫叶呀！', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 20, '衣食住是指人们生活所必需的衣服、食物和娱乐。', '衣食住是指衣服、食物和房子。', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 21, '空气加热之后，空气的体积会缩小。', '空气加热之后，体积会增大。其体积随着温度的不同而不同。', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 22, '颜色的三要素中“明度”是指颜色清澈和浑浊的程度。', '颜色的明亮和黑暗的程度称为“明度”，清澈和浑浊的程度称为彩度。', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 23, '吸血的蚊子是雄蚊子。', '吸血的蚊子是雌蚊子，雄蚊子一般吸食植物的茎液(树叶)。', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 100, '最初通过完成任务会送你休闲椅子的男孩叫皮罗', '人家不叫皮罗，叫皮奥，你们有没有获得皮奥做的休闲椅子呢？', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 101, '抽奖获得“月亮弯”椅子以后，可以向其他玩家卖出很高的价钱哦', '“月亮弯”很漂亮也很稀有，但是它不可以交易，不过能获得月亮弯是很幸运的哦~', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 102, 'C大调时，在五线谱的下加一间和第二线分别唱MI、SO', '唱对了么？仔细回忆一下，第二线是唱SO，不过下加一间是唱RE哦~', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 103, '上下排列的红绿灯的排列从上到下一次为红、黄、绿', '这是生活中的小常识哦，大家可以验证一下，就是红、黄、绿', 'o');
