INSERT INTO `wz_oxdata` VALUES (3, 107, '神射手可以在神木村接到任务通过努力抚养一只冰凤凰', '神射手可以抚养的是火凤凰，箭神才可以抚养冰凤凰，但是2种神鸟都很强大哦', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 108, '冒险岛的船长有机会获得自己的战船，还可以请海鸥帮忙战斗', '船长真的可以驾驶拉风稳重的战船，还能呼唤章鱼和海鸥助战！', 'o');
