INSERT INTO `wz_oxdata` VALUES (3, 110, '夏天下雨之后会变凉快的原因是因为固体→液体→气体(吸热反应)。', '是因为固体→液体→气体：吸热反应。', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 111, '冬天睡觉叫冬眠，夏天睡觉叫做夏眠。', '夏眠的动物有玉筋鱼、海参、瓢虫等。', 'o');
