INSERT INTO `wz_oxdata` VALUES (3, 116, '冰雷魔导师和火毒魔导师最后还可以修成逆属性招数', '确实是这样，魔导师借助科学与魔法的双重力量可以习得逆属性的招数，是不是很酷很强大？', 'o');
