INSERT INTO `wz_oxdata` VALUES (3, 119, '镜子能照出人影是因为光的反射现象', '镜子投影是光的反射造成的，同时也与反射物的材料有关，所以镜子可以照得更加清晰', 'o');
INSERT INTO `wz_oxdata` VALUES (3, 120, '近视眼镜的镜片是凸透镜', '虽然镜片一面看上去是凸出的，但是近视镜片是凹透镜做的', 'x');
INSERT INTO `wz_oxdata` VALUES (3, 121, '商城里卖的气球都是勇士部落酋长用嘴吹起来的', '商城的气球都会飘起来，而人吹的气球是飘不起来的，所以这是胡说的', 'x');
