INSERT INTO `wz_oxdata` VALUES (4, 102, '黄昏之露可以恢复MP5000点。', '恢复MP5000点。', 'o');
INSERT INTO `wz_oxdata` VALUES (4, 103, '清晨之露可以恢复HP4000点。', '恢复HP4000点。', 'x');
INSERT INTO `wz_oxdata` VALUES (4, 104, '矿泉水在24小时排档、简、拜伦、哈娜、豪素夫、米舍凯那里有售。', '明珠港的简不卖矿泉水。', 'x');
INSERT INTO `wz_oxdata` VALUES (4, 105, '镇痛剂只有在地球防御本部的珮珀那里可以买到。', '只有研制出镇痛剂的珮珀那里有售。', 'o');
INSERT INTO `wz_oxdata` VALUES (4, 106, 'NPC妖精珂丽尔在天空之城的武器商店里。', '妖精珂丽尔在天空之城的杂货商店里。', 'x');
INSERT INTO `wz_oxdata` VALUES (4, 107, '美味的香梭鱼和各种蔬菜一起制作而成的香梭鱼串，可以恢复MP500点。', '香梭鱼(串)可以恢复MP250点。', 'x');
INSERT INTO `wz_oxdata` VALUES (4, 108, '日本炒面(双倍)比日本炒面可以多提高魔力10。', '日本炒面(双倍)比日本炒面可以多提高魔力5。', 'x');
INSERT INTO `wz_oxdata` VALUES (4, 109, '比章鱼串能多提高攻击力5分钟的蛋炒面的价格要贵一倍。', '章鱼串：2000金币，蛋炒面：4200金币', 'x');
INSERT INTO `wz_oxdata` VALUES (4, 110, '日式拉面(烤肉)、日式拉面(猪排)、日式拉面(海鲜)都可以恢复HP。', '都可以恢复HP。', 'o');
INSERT INTO `wz_oxdata` VALUES (4, 111, '出售拉面、日式拉面的拉面料理师NPC的名字是元泰。', '拉面料理师元泰出售各种拉面。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 1, '电灯是德国人发明的', '电灯这个给世界带来便捷的事物，是美国人爱迪生发明的', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 2, '明珠港的任务“简和野猪”完成之后，可以从简那里获得头盔防御卷轴。', '不是头盔防御卷轴，而是武器卷轴。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 3, '废弃都市组队任务在其他组队正在执行任务的时候无法入场。', '其他组队如果正在执行任务，则无法入场。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 4, '废弃都市的离家出走的少年阿勒斯的父亲是林中之城桑拿房的泰素夫。', '阿勒斯的父亲是射手村的长老斯坦。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 5, '完成约翰的粉红花篮任务之后，可以获得30个螺丝。', '从约翰那里获得30个螺丝。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 6, '地铁站服务员出售的工地B1、B2、B3入场费都是2000金币。', 'B1-500金币，B2-1200金币，B3-2000金币，价格各不相同。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 7, '废弃都市组队任务的等级限制是Lev20~Lev30。', '等级限制是21~30级。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 8, '冒险岛里可以帮你制作氧气桶的古怪科学家叫卡兹', '其实他叫秀兹，住在通天塔向水下世界的一个隐秘实验室里，有空去找找看吧。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 9, '休咪的任务完成后，3次都能获得人气度报酬。', '总共可以获得+3的人气度。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 10, '在萨比特拉玛的年轻的药的任务中，可以获得星石或月石。', '不是萨比特拉玛想要的东西的时候，得到月石。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 11, '废弃都市组队任务总共由5个阶段组成。', '必须要完成5个阶段的任务，也有不同阶段的奖励。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 12, '在&lt;炼金术士简>任务中，会3次要求玩家帮助搜集材料。', '只有3次全都搜集齐，才能完成任务。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 13, '&lt;萨比特拉玛的减肥药>任务中，如果找错药草完成了的话，会获得EXP 500。', '完成后获得500的经验值。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 14, '黑斧木妖比火野猪厉害', '这个用你们自己的身体去体会一下吧，火野猪比黑斧木妖更灵活，威力也更强', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 15, '五边形的内角和是720度', '多边形内角和计算是180×（N-2），那么五边形内角和就是540度哦', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 16, '组队任务&lt;时空裂缝>一共由9个阶段组成，只有6人的组队才能执行。', '等级限制是35~50。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 17, '在射手村完成名为“玛亚和奇怪的药”之后，可以从玛亚那里获得“褐色斗笠”。', '从玛亚那里可以获得“褐色斗笠”。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 100, '&lt;简和野猪>任务完成后，可以随机获得100%、60%、10%武器攻击卷轴。', '可以获得EXP 500、60%武器攻击卷轴。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 101, '任务地图忍苦树林一共有5个阶段组成。', '配制减肥药&lt;1.2阶段>，配制变年轻的药&lt;3.4.5阶段>', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 102, '休咪的任务按&lt;休咪丢失的钱团→钱袋→钱包>的顺序执行。', '第2个任务是&lt;休咪丢失的钞票>。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 103, '泰素夫任务中需要的特制烤鳗鱼的材料是猴子的香蕉、风独眼兽尾巴和猪的头。', '特制烤鳗鱼里没有用到猴子的香蕉。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 104, '任务地图沉睡森林由7个阶段组成。', '沉睡森林一共由7个阶段组成。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 105, '全部完成罗雯和诅咒娃娃任务所需要的诅咒娃娃的个数是2千3百个。', '各需要100个、200个、400个、600个、1000个。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 106, '足球运动的场上队员最多是每队11人', '大家比较清楚吧，每队有10名球员和1名守门员上场，但如因为犯规罚下，会使场上队员人数下降', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 107, '乒乓球被成为中国的“国球”', '目前为止确实如此，乒乓球因其在中国的普及率和国人的整体水平，被誉为中国的“国球”。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 108, '&lt;萨比特拉玛的年轻的药>任务完成后，人气度会提高2。', '可以获得人气度和经验值道具。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 109, '&lt;查里中士和物物交换>任务所有的人都可以执行，和角色等级无关。', '是新手也可以执行的任务。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 110, '&lt;阿尔法部队联络网>任务中登场的NPC有珀斯上尉、巴伯中士、查里下士、伊吉上等兵。', '登场的是珀斯上尉、巴伯下士、查里中士、伊吉上等兵。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 111, '50级以上才能执行的&lt;寻找上古魔书>任务，是除新手之外所有职业都可以执行的任务。', '除新手到55级以下的玩家外，所有的职业都可以执行。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 112, '要提炼黑暗水晶，必须完成&lt;寻找上古魔书>任务的一部分。', '必须完成任务中的阿尔卡斯特和黑暗水晶。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 113, '皮奥的废品再利用任务中，会提供一把休闲椅作为报酬。', '坐在休闲椅上，每10秒可以恢复HP50点。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 114, '[伊卡路斯的滑翔翼 ]任务只有在[好无聊]任务结束后，32级以上的玩家才能执行。', '伊卡路斯在废弃都市可以见到。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 115, '妖精维英委托的[帮忙写作业]任务只有在[伊卡路斯的热气球]任务之后才能执行。', '只有完成了[伊卡路斯的滑翔翼 ]任务的，10级以上的玩家可以执行。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 116, '任务战利品之一的魔女草叶子只要捕捉魔女怪物[巫婆]就可以获得。', '魔女草叶子只要攻击魔女草就可以获得。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 117, 'NPC邪摩斯委托的[为复活准备]任务完成之后，人气度会下降-2。', '获得和鞋子有关的卷轴，人气度下降。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 118, '[封印住神秘危险之力的仪式1]任务需要的道具是冰独眼兽给的阴森气息33个。', '冰独眼兽给的道具是阴森气息。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 119, '要执行[大海的遇难者]任务，必须要有SES求救信。', '必须要有从怪物身上掉落的SOS求救信。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 120, '[有关转职的教导]任务中，坤提出的问题一共有5个。', '只要答对3个问题就能进入下一个阶段。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 121, '足球世界杯、夏季奥运会、冬季奥运会都是每4年举行一次', '对阿，这些重大体育赛事，都是4年举行一次，被全世界的朋友期待着，受到举世瞩目与关注', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 122, '太阳系有8大行星', '目前太阳系8大行星，水星、金星、地球、火星、木星、土星、天王星、海王星，原本第九行星的冥王星，已不在此列。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 123, '中国古代的“文房四宝”是纸、笔、印、砚', '纸、笔、墨、砚才是中国古代的“文房四宝”', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 124, '中国古代的“四大发明”是造纸、火药、指南针、活字印刷', '这四大发明是中国古代人民智慧的结晶，比起西方提早了几百年几千年呢。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 125, '著名的侦探“福尔摩斯”是小说家柯南道尔塑造出来的', '大家都知道福尔摩斯，是不是也清楚这个名侦探的创造者呢？他就是柯南道尔。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 126, '《西游记》的作者是吴承恩，《水浒传》的作者是罗贯中', '中国四大名著知多少？《西游记》作者是吴承恩，但《水浒传》作者可是施耐庵哦', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 127, '组队任务“月妙的年糕”只有达到100级以上才能参加。', '月妙的年糕任务的限制等级是10级以上。', 'o');
INSERT INTO `wz_oxdata` VALUES (5, 128, '“扎昆任务”的等级限制是70级。', '扎昆任务的限制等级是50级。', 'x');
INSERT INTO `wz_oxdata` VALUES (5, 129, '组队任务“月妙的年糕”只要和射手村公园的NPC达尔米对话就可以入场。', '是NPC达尔利。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 1, '2次转职时，搜集30个黑珠，可以得到道具“英雄证书”。', '英雄证书是2次转职必需的道具。', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 2, '新手到了10级的时候，可以在战士、魔法师、弓箭手、飞侠中选择一个职业。', '魔法师在8级时就可以转职。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 3, '新手要想转职成为飞侠，要求运气至少在25以上。', '敏捷(DEX)必须在25以上。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 4, '新手第一次转职时，会获得1点技能点。', '新手转职时，会获得1点技能点。', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 5, '想要4转的话，需要3转的角色的等级达到120级以上。', '120级以上可以进行4次转职。', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 6, '魔法师可以使用瞬间移动技能——“快速移动”。', '魔法师可以使用传送。', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 7, '飞侠的技能隐身术可以在隐自状态下攻击怪物。', '在隐身状态下无法攻击怪物。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 100, '学习并使用枪战士的“神圣之火”之后，可以增加最大HP、MP各60%。', '全部掌握之后，可以各增加60%。', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 101, '弩弓手的技能中，“穿透箭”技能全部掌握后可以增加伤害180%。', '全部掌握穿透箭之后，可以增加180%的伤害。', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 102, '飞侠在跳跃的状态下也可以使用标枪技能“双飞斩”。', '飞侠在跳跃的状态下可以使用技能。', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 103, '新手要转职成为飞侠要去的地方是“废都酒吧”。', '转职时要去的地方是废都酒吧。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 104, '4转职业分为3个种类的职业是战士和法师。', '只有战士分为3种职业。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 105, '使用弓箭的弓箭手的转职顺序是[弓箭手 →猎人→ 射手→箭神]。', '是按照[猎人→射手→神箭手]的顺序转职。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 106, '使用短剑的飞侠的转职顺序是[飞侠→侠客→独行侠→隐士]。', '是按照[飞侠→侠客→独行侠→侠盗]的顺序转职。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 107, '4转后最终的职业加起来一共可以分为9种。', '战士职业3种+魔法师职业2种+弓箭手职业2种+飞侠职业2种=9', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 108, '金钱炸弹是引爆地上的钱，对附近的敌人进行攻击的技能。', '引爆地上的钱，给敌人造成伤害。', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 109, '召唤自己的分身，让怪物在一定时间内攻击自己分身的技能的名字是分身术。', '分身术发动后，怪物会在一段时间内攻击分身。', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 110, '刺客的“强力投掷”技能可以消耗3个飞标，投掷出大飞标。', '消费3个飞标，投掷出贯穿敌人的大飞标。', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 111, '使用独行侠的“落叶斩”技能，可以有一定的几率使怪物立刻死亡。', '有一定几率使怪物昏迷。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 112, '要学习龙骑士的“龙咆哮”技能，“龙之献祭”技能的等级需要在5级以上。', '“龙之献祭”技能的等级必须在3级以上。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 113, '要学习射手的“箭雨”技能，“烈火箭”必须达到3级以上。', '\"贯穿箭\"技能必须达到5级以上。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 114, '祭司的“圣光”技能可以攻击多个怪物。', '最多可以攻击6个怪物。', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 115, '祭司的“巫毒”技能即使成功，怪物的基本能力值也不会发生变化。', '基本能力值没有变化。', 'o');
INSERT INTO `wz_oxdata` VALUES (6, 116, '要使用射手的“分身术” 技能，需要1个召回石。', '不用召回石也可以使用。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 117, '遭到冰雷巫师的“冰咆哮”技能攻击时，会暂时被冻结。', '除冰属性外的怪物被冻结，最多只能同时6个怪物。', 'x');
INSERT INTO `wz_oxdata` VALUES (6, 118, '新手技能“恢复”的再使用冷却时间是15分钟。', '过了10分钟就可以使用。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 1, '最初创建角色登录后，开始的地方是[彩虹岛]开始的。', '冒险岛的故事最初开始的地方是[彩虹岛]。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 2, '创建角色的时候需要掷骰子。这时STR、DEX、INT、LUK总共给予的点数合计24点。', '合计25点。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 3, '冒险岛中最先遇到的NPC是“丽娜”。', '冒险岛中最先遇到的NPC是“希娜”。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 4, '乘坐各个村庄之间的出租车的时候，对没有转职的新人的折扣价是1折。', '新手只需要十分之一的金币就可以乘坐出租车。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 5, '废弃都市可以购买药水和卷轴等的药店的名字是“废都药店”。', '废弃都市可以购买药水的地方是“废都药店”。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 6, '在村子里，及时快没有HP了，从高处掉下来也不会死亡。', '即使在村子里，HP全部消耗完的话就会死亡。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 7, '要想进入隐藏地图，必须是10级以上已经转职的角色。', '谁都可以进入隐藏地图，没有限制。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 8, '《三国演义》作者是罗贯中，《红楼梦》作者是曹雪芹', '中国四大名著知多少？《三国演义》作者就是罗贯中，《红楼梦》是曹雪芹的作品', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 9, '在海边地图黄金海滩中，出售药水的大叔的名字是“拜伦”。', '药水商人NPC的名字是“拜伦”。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 100, '如果想邀请其他玩家和自己组队，只要直接右键点击目标角色进行邀请', '如果自己要当队长邀请他人，首先需要建立自己的组队才能邀请他人', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 101, '折旧贩卖现金道具的情况下，会返还35%的冒险岛抵用券。', '只返还30%。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 102, '如果在2次转职等级的31级以上转职，无法获得奖励SP+1。', '转职时都可以获得奖励SP。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 103, '用冒险岛抵用券可以赠送现金道具。', '用冒险岛抵用券无法赠送现金道具。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 104, '水下世界的动物园里一共有4个怪物。', '一共是蝙蝠怪、白雪人、白狼、漂漂猪和猪猪总共5个怪物。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 105, '鲸鱼岛的NPC纳努科带着4条哈士奇犬。', '带着褐色、黑色和灰色的哈士奇犬。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 106, '椰子树林和鲸鱼岛地图中的鲸鱼的额头上贴着橡皮膏。', '两个的额头上都贴着橡皮膏。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 107, '太公的小船地图中的太公的钓鱼台上粘着一片树叶。', '一共粘着3片树叶，但是钓鱼台上只有1片。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 108, '玩具塔93层的玩具工人2手里拿着锤子。', '其他的工人拿着其他工具。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 109, '水下世界是位于玩具塔地下的水下地图。', '水下世界是和通天塔相连接的地图。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 110, '创建家族需要100万金币。', '需要有150万金币才能创建家族。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 111, '家族的人数最多可以提高至30名。', '现在限制为30名。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 112, '要把家族人数从10名提高到15名需要50万金币。', '将家族人数从10名提高到15名需要50万金币。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 113, '家族公告只有家族会长可以使用。', '会长和副会长都可以使用家族公告功能。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 114, '家族解散时需要20万金币的费用。', '只有会长可以解散家族，需要20万金币的费用。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 115, '制作家族徽章需要500万金币的费用。', '家族徽章可以通过NPC蕾雅制作。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 116, '负责家族创建和家族徽章制作的NPC是哈拉克。', '负责制作家族徽章的 NPC是蕾雅。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 117, '在村子里的“荣耀公馆”里，可以查看家族的排名。', '在“荣耀之石”上可以查看家族的排名。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 118, '任务提示中，最多可以登录5个任务。', '可以登录5个任务，实时查看。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 119, '在家族对抗战中，到奖励阶段为止，一共有6个阶段构成。', '一共有7个阶段。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 120, '氢氧化钙俗称“生石灰”', '氢氧化钙俗称“熟石灰”，“生石灰”是氧化钙', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 121, '水下世界是直接与玩具塔地下相连接的水下地图。', '水下世界是与通天塔相连的水下地图', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 122, '在水下世界中，每10秒钟HP都会减少。', '如果没有氧气瓶或空气玲，每10秒钟HP都会减少。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 123, '水下世界的大海的遇难者NPC的名字是“鲁宾逊克鲁索”。', '就只是鲁宾逊。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 124, '童话村的七南和七诚兄弟中，哥哥是七南。', '七诚是哥哥，七南是弟弟。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 125, '使用非法软件作弊玩游戏，会导致封号。', '是的，为了你和他人的利益，请不要使用非法程序', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 126, '通过NPC“杜尔”可以向其他玩家发送特快邮件，费用是50,000。', 'NPC是杜宜，费用是5,000金币。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 127, '射手村的世界旅游向导的名字是“娜娜”。', '世界旅游向导的名字是“妮妮”。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 128, '射手村迷宫入口的卫兵“鲁克”是右手握着枪。', '鲁克是左手握着枪。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 129, '勇士部落的NPC“伊安”的父亲是“布鲁斯”。', 'NPC伊安的父亲确实是布鲁斯。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 130, '东部岩山II的NPC的名字是“战士转职教官”。', '东部岩山ⅱ的NPC的名字是芳博士。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 131, '皮亚奴斯出现的地图的名字是“皮亚奴斯的深海洞穴”。', '是“皮亚奴斯的洞穴”。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 132, '地球防御本部的鲁斯韦尔草原上的白外星人司令拄着拐杖。', '不是鲁斯韦尔草原，而是库尔兰草原。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 133, '干冰的化学成分是二氧化碳', '干冰就是二氧化碳的固态形式，常用于制造舞台“烟雾效果”，同时可以辅助灭火', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 134, 'NPC妙斯在水下世界动物园里。', 'NPC妙斯在水下世界动物园里。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 135, '使用现金道具发送的特快专递可以很快发送到收件的对方。', '是的，速度很快很方便，商城—其他—游戏，即可选购。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 136, '日本古代神社的亚希子手里拿着吸尘器。', '亚希子因为要打扫卫生，手里拿着扫帚。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 137, '一天有86410秒', '仔细想想，60秒/分，60分/小时乘起来结果起码要2个“0”结尾哦，一天有86400秒拉～', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 138, '上海城市广场上的驾驶员NPC的姓是林。', '上海城市广场上的驾驶员姓洪。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 139, '中国上海外滩的防具商人挽着袖子。', '两只手都插在裤子口袋里。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 140, '上海外滩的周的职业是巡警。', '周是警察处长。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 141, '中国上海外滩的吕现在正在打工。', '不是在打工，是小摊的老板。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 142, '在压力相同的条件下，受力面积越大，受到的压强也越大', '同样的压力，作用的范围面积越小，产生的压强就越大。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 143, '中国上海外滩的摄影师赵挂着2:8的相机。', '摄影师赵挂着2:8的漂亮的相机。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 144, '中国徐州平原Ⅲ的赵小姐穿着漂亮的连衣裙。', '没有穿着连衣裙，而是穿着裤子。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 145, '8月30日和9月1日出生的人都是处女座', '对星座感兴趣的达人这下赚到了，这段时间出生的人都是处女座，处女座的小朋友有什么特点呢？', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 146, '2月18日和2月20日出生的人都是双鱼座', '2月18日的是水瓶座啦，2月20日是双鱼座，更难的问题是，2月19日到底算什么座呢？', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 147, 'Don\'t you like this quiz game?如果要回答“不，我很喜欢”，圈圈表示YES，叉叉表示NO，请大家两边站好', '老外很直白，只要考虑真实感受就行了，如果喜欢，就说“Yes,I do.”', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 148, '地球防御本部郊外的白外星人哥雷，其实是个坏蛋', '这个外星人假装可怜来欺骗我们，大家去揭穿他的丑恶行径吧，为了冒险岛的和平努力！', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 149, '玛加提亚村的人造人机器人的名字是人造人B。', '玛加提亚村的人造人机器人的名字是人造人A。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 150, '冒险岛的洗能力点卷轴一个要卖1000点', '根本不用那么多点啦，100点就可以买到洗能力卷轴了，加错点随时可以洗哦，很方便达！', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 151, '如果不设置2重密码，就无法获得被盗处理。', '被盗申报需要在设置2重密码后才能进行。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 152, '现金商店里出售的装备道具可以提高能力值。', '现金商店里的道具不能提高能力值。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 153, '蒙特鸠的会长是卡森，卡帕莱特的会长是麦麦德。', '卡森和卡帕莱特分别是蒙特鸠协会和卡帕莱特协会的会长。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 154, '冒险岛聊天器最多可以邀请2名好友聊天。', '冒险岛聊天器包括本人在内最多可以和3个人对话。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 155, '被封印的道具限制1周最多解除1次。', '可以通过客服中心1周解除1次。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 156, '快递道具如果不及时领取，100日之后会消失。', '快递道具的保管期限是30天。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 157, '卡米拉害怕尤塔的猪猪农场上的铁甲猪。', '卡米拉害怕的是漂漂猪。', 'x');
INSERT INTO `wz_oxdata` VALUES (7, 158, '童话村的燕子因为道功从小喂它们吃蟠桃和神仙汤，所以变得很聪明。', '由于吃了蟠桃和神仙汤，童话村的燕子变聪明了。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 159, '玛加提亚的琦尼是妖精和人类的混血儿。', '玛加提亚的琦尼是妖精和人类生的孩子。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 160, '玛加提亚的杂货商人哲里也出售宠物的食物。', '玛加提亚的杂货商人哲里那里也可以买到宠物的食物。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 161, '废弃都市的所有悬赏公告牌都损坏了。', '废弃都市没有完整的悬赏公告牌。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 162, '童话村的乐夫穿着可以看到肚脐的衣服。', '童话村的乐夫那里可以看到漂亮的肚脐。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 163, '送货员杜宜鞋子的颜色是褐色的。', '送货员杜宜穿着一双漂亮的褐色鞋子。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 164, '勇士部落的仓库老板王先生是独眼龙。', '在勇士部落可以见到独眼龙王先生。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 165, '射手村的玛亚旁边有一个红色的邮箱。', '玛亚的房子的入口处有一个可怕的红色邮箱。', 'o');
INSERT INTO `wz_oxdata` VALUES (7, 166, '特别节日要进入特殊的万圣节古堡地图时，最好穿着特殊服饰', '把自己打扮成小鬼小怪哦，不然很难进阴森的古堡，特定时间才买得到带有H标准的鬼怪服饰', 'o');
INSERT INTO `wz_oxdata` VALUES (8, 1, '第一届世界杯是在意大利召开的。', '第一届世界杯是在乌拉圭召开的，第二界是在意大利。', 'x');
INSERT INTO `wz_oxdata` VALUES (8, 2, '世界杯每隔2年举行一次。', '每隔4年举行一次。', 'x');
INSERT INTO `wz_oxdata` VALUES (8, 3, '商城里一些服饰有标注“E”，是说明商品有折扣', '不是这样哦，“E”标注的商品是组合在一起会产生特效！', 'x');
INSERT INTO `wz_oxdata` VALUES (8, 4, '商城的“达人卡”是很划算的会员卡，可以在专区随便拿衣服', '超合算的体验式会员卡啊，在有效期内，可以无限量在达人专区把衣服免费带走！', 'o');
INSERT INTO `wz_oxdata` VALUES (8, 5, '足球是11个人的运动，而篮球是6个人的运动。', '篮球是5个人玩的运动。', 'x');
INSERT INTO `wz_oxdata` VALUES (8, 6, '奥林匹克五环旗中，代表亚洲的颜色是黄色。', '奥运五环旗中的黄色象征亚洲。', 'o');
INSERT INTO `wz_oxdata` VALUES (8, 100, '天空之城的艾利逊送给奈洛一条项链作礼物，奈洛是艾利逊暗恋的姑娘', '奈洛其实是艾利逊可爱的小猫啦，不过艾利逊还是对奈洛非常非常关爱呀~', 'x');
INSERT INTO `wz_oxdata` VALUES (8, 101, '在网球中，大满贯表示包揽US公开赛、法国公开赛、澳大利亚公开赛、温布尔登公开赛的冠军。', '包揽4大主要赛事的冠军被称为大满贯。', 'o');
INSERT INTO `wz_oxdata` VALUES (8, 102, '高尔夫中，比标准杆少1杆被称为小鸟球，少2杆被称为老鹰球，少3杆被称为双柏忌。', '少3杆被称为双老鹰。', 'x');
INSERT INTO `wz_oxdata` VALUES (8, 103, '制作送给“奈洛的项链”的材料需要去魔法密林用钻石和妖精艾温兑换', '其实只要去商城用心寻找一下只需1个金币就可购买铃铛和红丝带，就可制作奈洛的项链啦！', 'x');
INSERT INTO `wz_oxdata` VALUES (8, 104, '宠物“进化龙”不仅技能丰富，还可以进化成多种不同形态，其中黑龙很稀有', '这些说得全是真的哦，拥有黑龙的玩家都是超幸运的呀！有没有试过“变身”啊？', 'o');
INSERT INTO `wz_oxdata` VALUES (8, 105, '新一代进化宠“罗伯”除了有稀有形态进化，还有超稀有形态的“变异”呢', '太厉害了，除了有“金色形态”的进化，罗伯还有可能进化成超稀有形态的黑猩猩“金刚”啊！！', 'o');
INSERT INTO `wz_oxdata` VALUES (8, 106, '在宠物商人和商城内购买的宠物食品都是所有宠物都可以吃的', '宠物商人那买的宠物食品是通用的，但商城内食品是针对不同宠物让宠物成长更迅速！', 'x');
INSERT INTO `wz_oxdata` VALUES (8, 107, '在足球中发任意球的时候，对方运动员距离踢球的运动员的距离必须在9.15米以上。', '如果进入9.15m内会受到警告。', 'o');
INSERT INTO `wz_oxdata` VALUES (8, 108, '将游泳设为正式比赛项目的奥运会是1896年的第一届奥运会。', '是从1900年的第二届奥运会时被设为正式比赛项目的。', 'x');
INSERT INTO `wz_oxdata` VALUES (8, 109, '商城大礼包，不仅比购买多个单品便宜，而且还可以购买到单品中买不到的商品', '啊啊，大礼包真的是很棒啊，不仅价格有优惠，还有特别贩售版，平时想买也买不到哦', 'o');
